mockup.css:
.mock-section-inset-panel { background: #1c2b24; padding: 6cqw; }
.mock-section-inset-panel .panel { background: #f4f1e6; color: #17201b; block-size: 100%; padding: 0 7cqw;
  font-family: var(--f-sans); display: grid; grid-template-columns: 1fr auto;
  align-items: center; gap: 5cqw; }
.mock-section-inset-panel h4 { margin: 0 0 1.6cqw; font-family: var(--f-serif); font-size: 4.2cqw;
  line-height: 1.05; letter-spacing: -.02em; max-width: 18ch; }
.mock-section-inset-panel p { margin: 0; font-size: 1.5cqw; line-height: 1.5; opacity: .7; max-width: 34ch; }
.mock-section-inset-panel .cta { background: #17201b; color: #f4f1e6; padding: 1.5cqw 3.2cqw;
  font-size: 1.3cqw; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; }
